"""Fixed-point Verilog biquad cascade + coefficient/test-vector files.

The arithmetic matches ``quantize.simulate_fixed`` bit for bit:
    acc = b0 x + b1 x1 + b2 x2 - a1 y1 - a2 y2      (full precision)
    y   = sat_DW((acc + 2^(FRAC-1)) >>> FRAC)
Each section registers its output (one cycle latency per section).
"""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

import numpy as np

from ..quantize import QFormat, float_to_data, simulate_fixed

BIQUAD_V = """\
// biquad_df1.v -- fixed-point direct-form-I biquad (generated by filter_tuner)
// y[n] = sat((b0 x[n] + b1 x[n-1] + b2 x[n-2] - a1 y[n-1] - a2 y[n-2]) >> FRAC)
// with round-half-up before the shift. a0 is implicitly 1.
`default_nettype none

module biquad_df1 #(
    parameter integer DW   = 16,   // data width (Q1.DW-1)
    parameter integer CW   = 16,   // coefficient width
    parameter integer FRAC = 14,   // coefficient fractional bits (>= 1)
    parameter signed [CW-1:0] B0 = 0,
    parameter signed [CW-1:0] B1 = 0,
    parameter signed [CW-1:0] B2 = 0,
    parameter signed [CW-1:0] A1 = 0,
    parameter signed [CW-1:0] A2 = 0
) (
    input  wire                 clk,
    input  wire                 rst,
    input  wire                 in_valid,
    input  wire signed [DW-1:0] x,
    output reg                  out_valid,
    output reg  signed [DW-1:0] y
);
    localparam integer AW = DW + CW + 3;
    localparam [AW-1:0] ONE = 1;
    localparam signed [AW-1:0] HALF = ONE << (FRAC - 1);
    localparam signed [AW-1:0] YMAX = (ONE << (DW - 1)) - ONE;
    localparam signed [AW-1:0] YMIN = -(ONE << (DW - 1));

    reg signed [DW-1:0] x1, x2, y1, y2;

    wire signed [AW-1:0] acc = B0 * x + B1 * x1 + B2 * x2 - A1 * y1 - A2 * y2;
    wire signed [AW-1:0] shf = (acc + HALF) >>> FRAC;
    wire signed [DW-1:0] ysat = (shf > YMAX) ? YMAX[DW-1:0] :
                                (shf < YMIN) ? YMIN[DW-1:0] : shf[DW-1:0];

    always @(posedge clk) begin
        if (rst) begin
            x1 <= 0; x2 <= 0; y1 <= 0; y2 <= 0;
            y <= 0; out_valid <= 1'b0;
        end else begin
            out_valid <= in_valid;
            if (in_valid) begin
                x1 <= x;  x2 <= x1;
                y1 <= ysat; y2 <= y1;
                y  <= ysat;
            end
        end
    end
endmodule

`default_nettype wire
"""


@dataclass(frozen=True)
class VerilogBundle:
    files: dict[str, str]   # filename -> contents

    def write(self, directory: str | Path) -> list[Path]:
        d = Path(directory)
        d.mkdir(parents=True, exist_ok=True)
        out = []
        for name, text in self.files.items():
            p = d / name
            p.write_text(text)
            out.append(p)
        return out


def _lit(v: int, bits: int) -> str:
    return f"{bits}'sh{int(v) & ((1 << bits) - 1):0{(bits + 3) // 4}X}"


def _hex(v: int, bits: int) -> str:
    return f"{int(v) & ((1 << bits) - 1):0{(bits + 3) // 4}X}"


def cascade_top(ints: np.ndarray, fmt: QFormat, data_bits: int,
                name: str = "filter_cascade", output_gain: float = 1.0) -> str:
    cw, frac, dw = fmt.word_bits, fmt.frac_bits, data_bits
    n = len(ints)
    lines = [
        f"// {name}.v -- {n}-section biquad cascade (generated by filter_tuner)",
        f"// coefficients {fmt.label()}, data Q1.{dw - 1}, latency {n} cycles",
    ]
    if abs(output_gain - 1.0) > 1e-12:
        lines.append(f"// sections are scaled: multiply y by {output_gain:.9g} to restore H(z)")
    lines += [
        "`default_nettype none",
        "",
        f"module {name} (",
        "    input  wire                 clk,",
        "    input  wire                 rst,",
        "    input  wire                 in_valid,",
        f"    input  wire signed [{dw - 1}:0] x,",
        "    output wire                 out_valid,",
        f"    output wire signed [{dw - 1}:0] y",
        ");",
        f"    wire signed [{dw - 1}:0] s_data [0:{n}];",
        f"    wire                s_valid [0:{n}];",
        "    assign s_data[0]  = x;",
        "    assign s_valid[0] = in_valid;",
        "",
    ]
    for i, sec in enumerate(ints):
        b0, b1, b2, _, a1, a2 = (int(c) for c in sec)
        lines += [
            "    biquad_df1 #(",
            f"        .DW({dw}), .CW({cw}), .FRAC({frac}),",
            f"        .B0({_lit(b0, cw)}), .B1({_lit(b1, cw)}), .B2({_lit(b2, cw)}),",
            f"        .A1({_lit(a1, cw)}), .A2({_lit(a2, cw)})",
            f"    ) u_sec{i} (",
            "        .clk(clk), .rst(rst),",
            f"        .in_valid(s_valid[{i}]), .x(s_data[{i}]),",
            f"        .out_valid(s_valid[{i + 1}]), .y(s_data[{i + 1}])",
            "    );",
            "",
        ]
    lines += [
        f"    assign y = s_data[{n}];",
        f"    assign out_valid = s_valid[{n}];",
        "endmodule",
        "",
        "`default_nettype wire",
        "",
    ]
    return "\n".join(lines)


def coeff_mem(ints: np.ndarray, fmt: QFormat) -> str:
    lines = ["// b0 b1 b2 a1 a2 per section, two's complement hex"]
    for sec in ints:
        b0, b1, b2, _, a1, a2 = sec
        lines.append(" ".join(_hex(v, fmt.word_bits) for v in (b0, b1, b2, a1, a2)))
    return "\n".join(lines) + "\n"


def testbench(name: str, data_bits: int, n_samples: int) -> str:
    dw = data_bits
    return f"""\
// tb_{name}.v -- self-checking testbench (generated by filter_tuner)
// Expected outputs come from the bit-accurate Python model.
`timescale 1ns/1ps
module tb_{name};
    reg clk = 0, rst = 1, in_valid = 0;
    reg  signed [{dw - 1}:0] x = 0;
    wire signed [{dw - 1}:0] y;
    wire out_valid;
    reg [{dw - 1}:0] stim [0:{n_samples - 1}];
    reg [{dw - 1}:0] expd [0:{n_samples - 1}];
    integer i, k, errors;

    {name} dut (.clk(clk), .rst(rst), .in_valid(in_valid), .x(x),
               .out_valid(out_valid), .y(y));

    always #5 clk = ~clk;

    initial begin
        $readmemh("stimulus.mem", stim);
        $readmemh("expected.mem", expd);
        errors = 0; k = 0;
        repeat (3) @(posedge clk);
        rst = 0;
        for (i = 0; i < {n_samples}; i = i + 1) begin
            @(negedge clk);
            x = stim[i];
            in_valid = 1;
        end
        @(negedge clk);
        in_valid = 0;
        repeat (64) @(posedge clk);
        if (k != {n_samples}) begin
            $display("FAIL: got %0d outputs, expected {n_samples}", k);
            errors = errors + 1;
        end
        if (errors == 0) $display("PASS: {n_samples} samples bit-exact");
        else             $display("FAIL: %0d errors", errors);
        $finish;
    end

    always @(posedge clk) begin
        if (out_valid && k < {n_samples}) begin
            if (y !== $signed(expd[k])) begin
                if (errors < 10)
                    $display("mismatch at %0d: got %0d expected %0d", k, y, $signed(expd[k]));
                errors = errors + 1;
            end
            k = k + 1;
        end
    end
endmodule
"""


def test_vectors(ints: np.ndarray, fmt: QFormat, data_bits: int,
                 n: int = 512, seed: int = 0) -> tuple[np.ndarray, np.ndarray]:
    """Impulse + chirp + noise stimulus at -6 dBFS and its exact model output."""
    rng = np.random.default_rng(seed)
    t = np.arange(n)
    x = np.zeros(n)
    x[0] = 0.5
    third = n // 3
    x[third:2 * third] = 0.5 * np.sin(np.pi * (t[:third] / third) * t[:third] / 2)
    x[2 * third:] = rng.uniform(-0.5, 0.5, n - 2 * third)
    xi = float_to_data(x, data_bits)
    yi = simulate_fixed(ints, fmt.frac_bits, xi, data_bits)
    return xi, yi


def bundle(ints: np.ndarray, fmt: QFormat, data_bits: int = 16,
           name: str = "filter_cascade", output_gain: float = 1.0,
           n_vectors: int = 512) -> VerilogBundle:
    if fmt.frac_bits < 1:
        raise ValueError("Verilog export needs at least 1 fractional coefficient bit")
    xi, yi = test_vectors(ints, fmt, data_bits, n_vectors)
    return VerilogBundle({
        "biquad_df1.v": BIQUAD_V,
        f"{name}.v": cascade_top(ints, fmt, data_bits, name, output_gain),
        f"tb_{name}.v": testbench(name, data_bits, n_vectors),
        "coeffs.mem": coeff_mem(ints, fmt),
        "stimulus.mem": "\n".join(_hex(v, data_bits) for v in xi) + "\n",
        "expected.mem": "\n".join(_hex(v, data_bits) for v in yi) + "\n",
    })
